@startuml
class Well {
  +code : string
  +pollutionRate() : float
}

class OnshoreWell extends Well {
  +surfaceExtension : float
}

class OffshoreWell extends Well {
  +yearOfInstallation : int
  +pollutionRate() : float
}

class Company {
  +taxCode : string
  +numberOfEmployees : int
}

class GeographicalArea {
  +code : string
  +degreeOfEnvironmentalImportance : int
}

class Extraction {
  +quantity : float
}

Well "0..*" -- "0..*" Company : extraction
(Well, Company) .. Extraction

Well "0..1" -- "0..1" GeographicalArea : located in
@enduml

